"""Predicted activation of component 3845 of layers.15.mlp.down_proj in Qwen3-1.7B.

What it does, in plain terms: this component is a "predicate verb" detector. It is
strongly positive on auxiliary and modal verbs (is, was, are, has, would, can, must, 's),
moderately positive on main verbs, and most positive when a verb directly follows a
subject pronoun ("we need", "They say"), a relative word ("which requires") or an
auxiliary. It is negative on determiners and articles ("the", "a", "this"), on a verb
right after a determiner ("the return"), and slightly negative on punctuation and on
the word after a relative pronoun. Everything else is about zero.

Word classes come from the WordNet library (is a word a verb) and fixed word lists. The
model needs more than word classes to do better: the same word can differ by a lot in
activation depending on context, and a per-token lookup table would explain about 28% of
the variance (vs about 15% here).
"""

from wordnet import parts_of_speech

READS = ()

AUX = set("is was are were be been being am has have had do does did will would can "
          "could should shall may might must 's ’s".split())
SUBJECT_PRONOUNS = set("i you he she it we they there here".split())
RELATIVE_WORDS = set("that which who what whom whose".split())
DETERMINERS = set("the a an this these those their his her its our my your some all any each every no".split())


def is_verb(word):
    return word.isalpha() and word.islower() and "verb" in parts_of_speech(word)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    before = prefix.token_strings[-2].strip().lower() if same_doc else ""
    if word in AUX:
        value = 2.7
    elif word in DETERMINERS:
        value = -0.3
    elif is_verb(word):
        value = 0.8
        if before in SUBJECT_PRONOUNS:
            value += 2.6
        elif before in RELATIVE_WORDS:
            value += 2.1
        elif before in AUX:
            value += 1.8
        elif before in DETERMINERS:
            value -= 0.7
    elif word == "to":
        value = 0.3
    elif not any(c.isalnum() for c in word):
        value = -0.15
    else:
        value = 0.0
    if before in SUBJECT_PRONOUNS and word not in AUX:
        value += 0.8
    if before in RELATIVE_WORDS:
        value -= 0.3
    return carry, float(value)

"""Coordinating commas: the component fires on a comma that follows a full phrase
inside a sentence, where the sentence goes on with another list item, appositive or
clause ("...differ much in size, depending on age"; "...the gutters and overhangs").

A comma that closes a short opening phrase of two words or fewer ("However,", "So,",
"Then,") gets only a small value (0.5); other commas get 3. " and" / " und" / " et" /
" и" get a small positive value (0.5), " or" a negative one (-1). Everything else is 0.

The program tracks how many words have passed since the last sentence break (a
period, question or exclamation mark, semicolon, colon, newline or quote) and resets
at each new document. That count is the only context it uses.
"""

READS = ()

COMMAS = {",", "，", "、"}
CONJUNCTIONS = {" and", " und", " et", " и"}
SENTENCE_BREAKS = ".!?;:\n\""


def step(carry, prefix, upstream):
    words, doc = carry if carry else (0, None)
    if prefix.document_ids[-1] != doc:
        words = 0
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if token in COMMAS:
        value = 0.5 if words <= 2 else 3.0
    elif token in CONJUNCTIONS:
        value = 0.5
    elif token == " or":
        value = -1.0
    else:
        value = 0.0
    if any(ch in token for ch in SENTENCE_BREAKS):
        words = 0
    elif any(ch.isalpha() for ch in token):
        words += 1
    return (words, doc), float(value)

"""Demonstrative determiners ("this", "that", "these", "those", "such", "same", and
their equivalents in other languages) and the noun they introduce.

On a demonstrative the component is negative, most strongly when it follows a
preposition ("in this case", "for these reasons") and only mildly after a verb or
at a clause start. On the noun right after a demonstrative it is positive, most for
abstract nouns ("this study", "this question", "this phenomenon"). Other referring
words ("the following", "above", "each", "both") are mildly negative; "here", "them"
and "it" mildly positive. Everything else predicts 0.
"""
from collections.abc import Mapping

import wordnet

READS: tuple[str, ...] = ()

DEMONSTRATIVES = {
    "this", "that", "these", "those", "such", "same",
    "cette", "ce", "ces", "este", "esta", "estos", "estas", "diesem", "dieser",
    "diese", "dieses", "この", "その", "이", "그", "该", "questo", "questa", "cet",
    "deze", "aquel", "этот", "этой", "эти",
}  # fmt: skip
PREPOSITIONS_STRONG = {"in", "at", "on", "under", "during", "within", "through", "between", "among"}
PREPOSITIONS = {"for", "from", "with", "by", "of", "to", "after", "before", "about", "into", "over", "across"}
ACTION_VERBS = {"do", "does", "did", "like", "compute", "fix", "solve", "use", "test", "try", "write", "make", "achieve", "understand", "check", "verify", "know", "notice"}
CLAUSE_START = {"", ".", ",", ";", ":", "!", "?", "and", "but", "or", "(", ")", '"', "\n"}
ABSTRACT_NOUNS = {"noun.event", "noun.act", "noun.state", "noun.phenomenon", "noun.cognition", "noun.communication", "noun.process"}
REFERRING = {
    "following": -2.6, "above": -1.4, "each": -1.9, "both": -2.0, "similar": -2.3,
    "present": -1.7, "latter": -4.4, "previous": -1.9, "respective": -2.8,
    "preceding": -5.0, "aforementioned": -7.0,
}  # fmt: skip
PRONOUNS = {"here": 1.7, "them": 1.5, "it": 0.6}


def word(token):
    return token.strip().lower()


def same_document(prefix):
    return len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]


def step(carry, prefix, upstream: Mapping):
    cur = word(prefix.token_strings[-1])
    before = word(prefix.token_strings[-2]) if same_document(prefix) else ""
    if cur in DEMONSTRATIVES:
        if before in PREPOSITIONS_STRONG:
            return carry, -11.0
        if before in PREPOSITIONS:
            return carry, -6.0
        if before in ACTION_VERBS:
            return carry, 1.3
        if before in CLAUSE_START:
            return carry, -3.4
        return carry, -1.5
    if before in DEMONSTRATIVES and cur.isalpha():
        cats = wordnet.categories(cur)
        if not any(c.startswith("noun.") for c in cats):
            return carry, 0.0
        if cats & ABSTRACT_NOUNS:
            return carry, 2.0
        return carry, 1.0
    if cur in REFERRING:
        return carry, REFERRING[cur]
    return carry, PRONOUNS.get(cur, 0.0)

"""Component p-82af68dd@100000/layers.15.mlp.down_proj:3877 (MLP down-projection feature).

What it is: a rank-one piece of layer 15's MLP output. Its activation is its MLP-hidden
neuron 3877 (plus a few small neighbours) read out through one direction, so its value is
diffuse and small (std ~0.31, mostly within +-0.8). It is almost never important
(CI > 0.1 at about 1 token in 10 million), and no simple concept predicts its value well.

What this program does: a word-list rule. Most tokens get the component's typical value
(about -0.03). A few word groups shift it:
  - restrictive words ("only", "except", "simply", "primarily"): strongly negative;
  - chat and tool-call markup (<|im_start|>, <|im_end|>, <tool_call>, ...): negative;
  - code-path and command words ("workspace", "command", "@Override"): positive.
The shifts are the mean activations of those tokens in training text. The program explains
well under 1% of the variance: it is a readable sketch of what the component leans toward,
not a faithful model of it.
"""

READS = ()

MEAN = -0.0277
RESTRICTIVE = {"only", "Only", "except", "simply", "primarily"}
CHAT_MARKUP = {"<|im_start|>", "<|im_end|>", "<tool_call>", "</tool_call>", "</tool_response>", "<think>"}
CODE_PATH = {"workspace", "/workspace", "command", "@Override", "Override"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in RESTRICTIVE:
        value = -0.4
    elif word in CHAT_MARKUP:
        value = -0.35
    elif word in CODE_PATH:
        value = 0.45
    else:
        value = MEAN
    return carry, float(value)

"""Layer-15 MLP down_proj, component 3879: a "superlative is coming" feature.

What it does, in plain terms. This component's output pushes the next-word
prediction against superlatives ("most", "best", "largest", "first"). So its
activation is strongly negative on "the" (or another determiner) when the text
is opening a predicate or a partitive where a superlative or identifying phrase
is likely next: "X is the ___", "was the ___", "has the ___", "one of the ___",
"some of the ___". It is milder after a verb-like word or a preposition, and it
is mildly positive on a superlative or ordinal that follows "the" ("the first",
"the best"). Everything else is about zero.

The numbers are rounded means of the activation in each context, fitted on
training text; the word lists are plain English word classes. The program only
reads the last few words of the same document, as the model does.
"""

READS = ()

COPULA = {"is", "was", "are", "were", "be", "been", "being", "become", "became", "becomes", "am", "'s", "’s", "seems", "remains"}
DEFINITE = {"the", "la", "le", "el", "der", "die", "das", "il", "lo", "los", "las", "les"}
POSSESSIVE = {"my", "his", "her", "their", "its", "our", "your", "what", "all", "those", "these", "this", "that"}
QUANTIFIER = {"one", "two", "three", "some", "many", "much", "several", "all", "most", "more", "any", "both", "each", "few", "none"}
PREPOSITION = {"with", "as", "like", "for", "in", "to", "by"}
SUPERLATIVE = {"first", "last", "next", "second", "best", "most", "largest", "biggest", "highest", "lowest", "smallest", "greatest", "worst", "latest", "earliest", "oldest", "youngest", "nearest", "closest", "top", "least", "favorite", "fastest", "finest", "quickest", "only"}


def step(carry, prefix, upstream):
    # The last four words of this document, up to and including the current token.
    t = prefix.position
    docs = prefix.document_ids
    lo = max(0, t - 3)
    while lo < t and docs[lo] != docs[t]:
        lo += 1
    words = [s.strip().lower() for s in prefix.token_strings[lo : t + 1]]
    cur = words[-1]
    prev = words[-2] if len(words) > 1 else ""
    prev2 = words[-3] if len(words) > 2 else ""
    copula_near = any(w in COPULA for w in words[-4:-1])

    if cur in DEFINITE:
        if prev in COPULA:
            return carry, -3.4
        if prev == "of" and prev2 in QUANTIFIER:
            return carry, -2.4
        if copula_near:
            return carry, -1.2
        if prev in PREPOSITION:
            return carry, -0.7
        return carry, -0.6
    if cur in POSSESSIVE:
        return carry, -1.6 if prev in COPULA else -0.2
    if cur in SUPERLATIVE:
        return carry, 0.8 if prev in DEFINITE else 0.1
    return carry, 0.0

"""Component layers.15.mlp.down_proj:3880: a "things going wrong, and checking them" feature.

In plain terms: the component is switched on by words about trouble and correctness
(fail, error, problem, prevent, avoid, refuse, object, deny, punish, threaten, lost,
wrong, broken, damage, danger, verify, ensure, fix, check). It is strongest when such a
word is the main verb of a clause whose subject is a person or a modal ("they refuse",
"the speaker warns", "should fail", "to prevent"). Other verbs are mildly positive, and
verbs of feeling, thinking or talking a bit more so. Function words (to, of, the, and,
in, a, ...) are clearly negative; punctuation and nouns sit slightly below zero.
Its output direction promotes words such as "because", "warnings", "violate",
"interfere" and "danger", so it fires when a problem or conflict is the topic.

Predicted activation: a baseline per word class, plus a bonus for trouble words, plus a
bonus for a verb that follows a person, modal or "to", minus a penalty for a verb that
follows a determiner (there it is usually a noun, as in "the use of").

Not modelled: the sign and size that depend on the wider sentence, which is most of the
variance; this program explains only a small share of it.
"""

import functools

from wordnet import base_forms, categories, parts_of_speech

READS = ()

FUNCTION_WORDS = set(
    "to of and in the a an is was that with for on by from as or but be it which not".split()
)
TROUBLE = set(
    """error problem issue bug failure fail wrong broken damage harm danger dangerous loss
    lose lost losing defeat kill death disaster crisis pain bad poor worse negative threat
    threaten punish punished attack accuse accused criticize warn warning violate violation
    illegal invalid conflict object objected oppose opposition deny denied refuse reject
    prevent avoid resist resistance block hinder interfere obstruct suffer mistake crash
    exception fix resolve verify ensure check remove correct identify detect catch stop
    prohibit forbid ban sue sued complain complaint angry afraid worried trouble""".split()
)
PERSON_OR_MODAL = set(
    """he she they we i you it who speaker person people man woman will can may shall should
    would could must might to""".split()
)
DETERMINERS = set(
    "the a an this that these those its his her their our my your some any every".split()
)
MENTAL_VERB_CLASSES = {"verb.emotion", "verb.cognition", "verb.communication"}


@functools.lru_cache(maxsize=None)
def word_class(word):
    if not word.isalpha():
        return "symbol"
    if word in FUNCTION_WORDS:
        return "function"
    if "verb" in parts_of_speech(word):
        return "verb"
    return "word"


@functools.lru_cache(maxsize=None)
def is_trouble(word):
    return bool(({word} | set(base_forms(word))) & TROUBLE)


@functools.lru_cache(maxsize=None)
def is_mental_verb(word):
    return bool(categories(word, "verb") & MENTAL_VERB_CLASSES)


BASELINE = {"function": -0.3, "symbol": -0.1, "word": -0.05, "verb": 0.1}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip().lower() if same_doc else ""
    cls = word_class(word)
    value = BASELINE[cls]
    if cls == "verb":
        if prev in PERSON_OR_MODAL:
            value += 0.7
        if prev in DETERMINERS:
            value -= 0.3
        if is_mental_verb(word):
            value += 0.2
    if is_trouble(word):
        value += 0.9 + (0.2 if cls == "verb" else 0.0)
    return carry, float(value)
